{"cards": [{"node_code": "N_7feed2e3d90d2e39", "definition": "水路运输运营中防止水体污染的技术与管理，涵盖船舶污染物排放控制、港口污水垃圾处理、防污法规执行及环境监测。", "boundary": "本节点聚焦于“防污”这一特定安全维度，侧重运营过程中的污染预防、控制措施及合规管理。边界在于区分“防污”与“一般安全”（如防火、防事故归入其他兄弟节点）。若涉及防污设备（如油水分离器）的设计制造，归入船舶工程；若涉及航道疏浚中的环保工程，归入航道工程。本节点侧重操作规范、监测技术及管理制度。", "includes": ["船舶油污水、垃圾、废气等污染物的排放控制技术与规程", "港口及码头污水处理、固废管理及防污染设施运行维护", "水域防污染法规、标准、监测技术及事故应急处理"], "excludes": ["防污设备（如油水分离器、压载水处理系统）的结构设计与制造", "航道疏浚、整治过程中的环保工程技术（归入航道工程）"], "sibling_distinctions": [{"other_code": "N_c1296420bb692be5", "rule": "本节点侧重“环境污染”防控（水、气、固废），兄弟节点侧重“火灾”防控（防火、灭火）。"}, {"other_code": "N_6dba286c8e793f7a", "rule": "本节点侧重“人为/运营性”污染防控，兄弟节点侧重“自然气象/水文”灾害（洪水、台风）应对。"}], "cross_boundary_rule": "若内容涉及“防污设备的设计与制造”，主挂载船舶工程或港口工程；若涉及“防污操作规程、监测、管理”，主挂载本节点。"}, {"node_code": "N_77bb712ec1acf43d", "definition": "水路运输领域内的公安保卫工作，涵盖水上治安、刑事侦查、反恐防暴、出入境边防检查及水上交通秩序维护。", "boundary": "本节点聚焦于“公安”职能，即维护水上公共安全、打击犯罪及秩序管理。边界在于区分“公安”与“海事监管”（海事侧重航行安全、防污染、船员资质，归入其他节点或综合管理）；区分“公安”与“一般安全管理”（如防火、防事故归入其他兄弟节点）。若涉及水上警察的执法程序、案件侦办、治安巡逻，归入本节点。", "includes": ["水上治安巡逻、刑事侦查、反恐防暴及突发事件处置", "水上交通秩序维护、违章处罚及出入境边防检查", "水运公安队伍管理、执法规范及水上警务技术"], "excludes": ["海事局主导的航行安全监管、防污染监管（归入海事管理或相关技术节点）", "船舶结构安全、港口设施安全设计（归入工程类）"], "sibling_distinctions": [{"other_code": "N_4792d8b2158e7cfb", "rule": "本节点侧重“治安与刑事”领域的公安执法，兄弟节点侧重“运输事故”（如碰撞、沉没）的技术分析与处理。"}, {"other_code": "N_0d1d14ed5f943106", "rule": "本节点侧重“公安执法”的具体工作，兄弟节点侧重“安全规章制度”的宏观制定与标准体系。"}], "cross_boundary_rule": "若内容涉及“水上交通事故”的现场处置，侧重技术救援归入事故处理，侧重治安调查归入本节点；若涉及“海事行政处罚”，需视具体执法主体，海事归海事，公安归本节点。"}, {"node_code": "N_6dba286c8e793f7a", "definition": "水路运输运营中应对洪水、台风、寒潮、高温等自然灾害的技术措施、预警机制、应急预案及设施防护。", "boundary": "本节点聚焦于“自然灾害”应对，侧重气象水文灾害的预防、监测、应急响应及设施保护。边界在于区分“自然灾害”与“人为事故”（如碰撞、火灾归入其他兄弟节点）；区分“运营应对”与“工程防护”（如堤坝、防波堤的设计施工归入港口/航道工程）。本节点侧重运营调度、船舶避风、人员撤离及应急物资管理。", "includes": ["防汛、防台风、防寒暑的预警监测、应急预案及调度指挥", "船舶、港口设施在极端天气下的防护措施及避风锚地管理", "自然灾害对水运影响分析及灾后恢复运营技术"], "excludes": ["防洪堤、防波堤、护岸等基础设施的结构设计与施工（归入港口/航道工程）", "船舶结构抗风浪能力设计（归入船舶工程）"], "sibling_distinctions": [{"other_code": "N_4792d8b2158e7cfb", "rule": "本节点侧重“自然灾害”（天灾）的预防与应对，兄弟节点侧重“运输事故”（人祸或意外）的分析与处理。"}, {"other_code": "N_7feed2e3d90d2e39", "rule": "本节点侧重“气象水文”灾害应对，兄弟节点侧重“环境污染”防控。"}], "cross_boundary_rule": "若内容涉及“防台风设施（如系缆桩、防波堤）的设计”，主挂载港口/航道工程；若涉及“防台风调度、船舶避风、应急预案”，主挂载本节点。"}]}
